function escapeXml(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function uptimeStr(createdAt) {
  const created = new Date(createdAt);
  const now = new Date();
  const days = Math.floor((now - created) / 86400000);
  const years = Math.floor(days / 365);
  const remaining = days % 365;
  const months = Math.floor(remaining / 30);
  const parts = [];
  if (years) parts.push(`${years} yr${years !== 1 ? "s" : ""}`);
  if (months) parts.push(`${months} mo${months !== 1 ? "s" : ""}`);
  if (!parts.length) parts.push(`${days} days`);
  return parts.join(", ");
}

async function ghFetch(path, token) {
  const headers = {
    Accept: "application/vnd.github+json",
    "X-GitHub-Api-Version": "2022-11-28",
    "User-Agent": "rs4t-profile-card",
  };
  if (token) headers.Authorization = `Bearer ${token}`;
  return fetch(`https://api.github.com${path}`, { headers });
}

async function paginate(path, token) {
  let items = [];
  let page = 1;
  for (;;) {
    const sep = path.includes("?") ? "&" : "?";
    const res = await ghFetch(`${path}${sep}per_page=100&page=${page}`, token);
    const data = await res.json();
    if (!Array.isArray(data) || data.length === 0) break;
    items = items.concat(data);
    if (data.length < 100) break;
    page++;
  }
  return items;
}

async function getTotalCommits(repos, token) {
  let total = 0;
  for (const r of repos) {
    if (r.fork) continue;
    try {
      const res = await ghFetch(
        `/repos/${r.full_name}/commits?author=${USERNAME}&per_page=1`,
        token
      );
      const link = res.headers.get("Link") || "";
      const match = link.match(/[?&]page=(\d+)[^>]*>;\s*rel="last"/);
      if (match) {
        total += parseInt(match[1], 10);
      } else {
        const data = await res.json();
        total += Array.isArray(data) ? data.length : 0;
      }
    } catch (e) {
      // skip repos the API errors on rather than fail the whole card
    }
  }
  return total;
}

